def run(api):
    s = api.inspect("state")
    if s["probed"] and not s["green"] and not s["workers_paused"]:
        return
    if not s["signed"]:
        s = api.apply("verify_artifact")
    if not s["probed"]:
        s = api.apply("pause_batch_workers")
        s = api.apply("allocate_green")
        s = api.apply("warm_green")
        s = api.apply("probe_health")
    if s["healthy"]:
        if s["sticky_sessions"] and not s["drained"]:
            s = api.apply("drain_sticky_sessions")
        if not s["new_traffic"]:
            s = api.apply("switch_traffic")
        if s["blue"]:
            s = api.apply("retire_blue")
        if s["workers_paused"]:
            s = api.apply("resume_workers_after_release")
    else:
        if s["green"]:
            s = api.apply("discard_green")
        if s["workers_paused"]:
            s = api.apply("resume_workers_after_abort")

